/// <summary>
/// Extends SysOperationServiceController
/// </summary>
final class AVACRLCreditOverrunController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    AVACRLCreditOverrunController controller;

    controller = new AVACRLCreditOverrunController(classStr(AVACRLCreditOverrunService),
                                       methodStr(AVACRLCreditOverrunService, startOperation),
                                       SysOperationExecutionMode::Synchronous);

    //controller.parmDialogCaption("Sample");
    controller.startOperation();
}

/// <summary>
/// default description of class
/// </summary>
/// <returns>ClassDescription</returns>
protected ClassDescription defaultCaption()
{
    return "@NDX:NXACRLCreditOverrunCoface";
}
